{
  "name": "EduAnalytics - AI Student Performance Insights",
  "description": "A comprehensive student performance analysis platform that transforms Excel data into multi-dimensional insights using Gemini AI and interactive visualizations.",
  "requestFramePermissions": []
}

export interface StudentRecord {
  id: string;
  name: string;
  class: string;
  scores: Record<string, number>;
  totalScore: number;
  averageScore: number;
  rankInClass?: number;
  rankInSchool?: number;
}

export interface AnalysisState {
  students: StudentRecord[];
  subjects: string[];
  classes: string[];
  schoolStats: {
    average: number;
    max: number;
    min: number;
    subjectStats: Record<string, { average: number; max: number; min: number }>;
  };
}

export interface AIInsight {
  title: string;
  content: string;
  type: 'success' | 'warning' | 'info';
}

declare global {
  interface Window {
    XLSX: any;
  }
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisState } from "../types";

export const getAIInsights = async (analysis: AnalysisState) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const summary = {
    totalStudents: analysis.students.length,
    classes: analysis.classes,
    subjects: analysis.subjects,
    schoolAverage: analysis.schoolStats.average,
    subjectAverages: analysis.schoolStats.subjectStats
  };

  const prompt = `
    Based on the following student performance data summary, provide 4 critical insights for educators:
    Data Summary: ${JSON.stringify(summary)}

    The insights should cover:
    1. Overall academic health of the school.
    2. Specific subjects that need attention (weakest performance).
    3. High-performing areas to be maintained.
    4. Actionable pedagogical recommendations.

    Return the insights in a structured JSON format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING },
              type: { type: Type.STRING, enum: ['success', 'warning', 'info'] }
            },
            required: ["title", "content", "type"]
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("AI Insights Error:", error);
    return [
      {
        title: "Analysis Available",
        content: "Data processed successfully. Explore the charts below for detailed breakdowns.",
        type: "info"
      }
    ];
  }
};

import React, { useCallback } from 'react';
import { Upload, FileSpreadsheet, AlertCircle } from 'lucide-react';
import { StudentRecord, AnalysisState } from '../types';

interface FileUploadProps {
  onDataLoaded: (data: AnalysisState) => void;
  setLoading: (loading: boolean) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded, setLoading }) => {
  const handleFileUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = window.XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = window.XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) throw new Error("Empty file");

        const firstRow = data[0];
        const keys = Object.keys(firstRow);

        // Identify special columns
        const nameCol = keys.find(k => k.includes('名') || k.toLowerCase().includes('name')) || keys[0];
        const classCol = keys.find(k => k.includes('班') || k.toLowerCase().includes('class')) || keys[1];
        const subjectCols = keys.filter(k => k !== nameCol && k !== classCol);

        const students: StudentRecord[] = data.map((row: any, index: number) => {
          const scores: Record<string, number> = {};
          let total = 0;
          subjectCols.forEach(sub => {
            const score = parseFloat(row[sub]) || 0;
            scores[sub] = score;
            total += score;
          });

          return {
            id: `s-${index}`,
            name: String(row[nameCol]),
            class: String(row[classCol]),
            scores,
            totalScore: total,
            averageScore: total / subjectCols.length
          };
        });

        // Calculate rankings
        students.sort((a, b) => b.totalScore - a.totalScore);
        students.forEach((s, idx) => s.rankInSchool = idx + 1);

        const classes = [...new Set(students.map(s => s.class))];
        classes.forEach(cls => {
          const classStudents = students.filter(s => s.class === cls);
          classStudents.sort((a, b) => b.totalScore - a.totalScore);
          classStudents.forEach((s, idx) => s.rankInClass = idx + 1);
        });

        // School stats
        const subjectStats: Record<string, any> = {};
        subjectCols.forEach(sub => {
          const vals = students.map(s => s.scores[sub]);
          subjectStats[sub] = {
            average: vals.reduce((a, b) => a + b, 0) / vals.length,
            max: Math.max(...vals),
            min: Math.min(...vals)
          };
        });

        onDataLoaded({
          students,
          subjects: subjectCols,
          classes,
          schoolStats: {
            average: students.reduce((a, b) => a + b, 0) / students.length,
            max: Math.max(...students.map(s => s.totalScore)),
            min: Math.min(...students.map(s => s.totalScore)),
            subjectStats
          }
        });
      } catch (err) {
        alert("Failed to parse Excel file. Please ensure it follows a standard format (Name, Class, Subjects...).");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  }, [onDataLoaded, setLoading]);

  return (
    <div className="flex flex-col items-center justify-center w-full p-12 border-2 border-dashed border-blue-200 rounded-2xl bg-white shadow-sm hover:border-blue-400 transition-all">
      <div className="bg-blue-50 p-4 rounded-full mb-4">
        <FileSpreadsheet className="w-12 h-12 text-blue-600" />
      </div>
      <h3 className="text-xl font-semibold text-gray-800 mb-2">Upload Grade Data</h3>
      <p className="text-gray-500 text-center max-w-sm mb-6">
        Upload your .xlsx file containing student names, classes, and subject scores.
      </p>
      <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg font-medium shadow-md transition-colors flex items-center gap-2">
        <Upload className="w-5 h-5" />
        Choose Excel File
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
      </label>
      <div className="mt-8 flex gap-4 text-xs text-gray-400 items-center">
        <div className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" />
          Supports multiple subjects
        </div>
        <div className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" />
          Auto rank calculation
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis,
  LineChart, Line, Legend, AreaChart, Area, Cell, PieChart, Pie
} from 'recharts';
import { 
  Users, BookOpen, GraduationCap, TrendingUp, ChevronRight, 
  Award, AlertTriangle, Lightbulb, Search
} from 'lucide-react';
import { AnalysisState, AIInsight } from '../types';
import { getAIInsights } from '../services/geminiService';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

const Dashboard: React.FC<{ data: AnalysisState }> = ({ data }) => {
  const [activeTab, setActiveTab] = useState<'school' | 'class' | 'student'>('school');
  const [selectedClass, setSelectedClass] = useState(data.classes[0]);
  const [selectedStudentId, setSelectedStudentId] = useState(data.students[0]?.id);
  const [aiInsights, setAiInsights] = useState<AIInsight[]>([]);
  const [aiLoading, setAiLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const fetchAI = async () => {
      setAiLoading(true);
      const insights = await getAIInsights(data);
      setAiInsights(insights);
      setAiLoading(false);
    };
    fetchAI();
  }, [data]);

  const selectedStudent = data.students.find(s => s.id === selectedStudentId);

  // Prep Chart Data
  const subjectAverageData = data.subjects.map(sub => ({
    name: sub,
    average: parseFloat(data.schoolStats.subjectStats[sub].average.toFixed(2)),
    max: data.schoolStats.subjectStats[sub].max
  }));

  const classPerformanceData = data.classes.map(cls => {
    const classStudents = data.students.filter(s => s.class === cls);
    return {
      name: cls,
      average: classStudents.reduce((a, b) => a + b.totalScore, 0) / classStudents.length
    };
  });

  const studentRadarData = data.subjects.map(sub => ({
    subject: sub,
    score: selectedStudent?.scores[sub] || 0,
    average: data.schoolStats.subjectStats[sub].average,
    fullMark: 100
  }));

  const filteredStudents = data.students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase())
  ).slice(0, 5);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard 
          icon={<Users className="w-6 h-6 text-blue-600" />} 
          title="Total Students" 
          value={data.students.length.toString()} 
          subtitle="All classes"
        />
        <StatCard 
          icon={<BookOpen className="w-6 h-6 text-green-600" />} 
          title="Subjects Analyzed" 
          value={data.subjects.length.toString()} 
          subtitle="Diverse curriculum"
        />
        <StatCard 
          icon={<GraduationCap className="w-6 h-6 text-purple-600" />} 
          title="Avg. Total Score" 
          value={data.schoolStats.average.toFixed(1)} 
          subtitle="Across school"
        />
        <StatCard 
          icon={<TrendingUp className="w-6 h-6 text-orange-600" />} 
          title="Top Score" 
          value={data.schoolStats.max.toString()} 
          subtitle="Academic excellence"
        />
      </div>

      {/* AI Insights Section */}
      <section className="bg-gradient-to-br from-indigo-50 to-white p-6 rounded-2xl border border-indigo-100 shadow-sm">
        <div className="flex items-center gap-3 mb-6">
          <Lightbulb className="w-6 h-6 text-yellow-500 fill-yellow-500" />
          <h2 className="text-xl font-bold text-gray-800">AI Pedagogical Insights</h2>
          {aiLoading && <div className="ml-auto flex items-center gap-2 text-sm text-indigo-400"><div className="w-2 h-2 bg-indigo-400 rounded-full animate-ping" /> Analyzing data...</div>}
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {aiInsights.map((insight, idx) => (
            <div key={idx} className={`p-4 rounded-xl border-l-4 ${
              insight.type === 'success' ? 'bg-green-50 border-green-500 text-green-800' :
              insight.type === 'warning' ? 'bg-amber-50 border-amber-500 text-amber-800' :
              'bg-blue-50 border-blue-500 text-blue-800'
            }`}>
              <h4 className="font-bold flex items-center gap-2 mb-1">
                {insight.type === 'warning' ? <AlertTriangle className="w-4 h-4" /> : <Award className="w-4 h-4" />}
                {insight.title}
              </h4>
              <p className="text-sm opacity-90 leading-relaxed">{insight.content}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Navigation Tabs */}
      <div className="flex gap-1 bg-white p-1 rounded-xl shadow-sm border border-gray-100 w-fit">
        <button 
          onClick={() => setActiveTab('school')}
          className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'school' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          School View
        </button>
        <button 
          onClick={() => setActiveTab('class')}
          className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'class' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          Class View
        </button>
        <button 
          onClick={() => setActiveTab('student')}
          className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'student' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          Student View
        </button>
      </div>

      {/* Tab Content */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {activeTab === 'school' && (
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-[400px]">
              <h3 className="text-lg font-bold text-gray-800 mb-6">Subject Averages vs School Max</h3>
              <ResponsiveContainer width="100%" height="80%">
                <BarChart data={subjectAverageData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip 
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                  />
                  <Bar dataKey="average" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Average Score" />
                  <Bar dataKey="max" fill="#dbeafe" radius={[4, 4, 0, 0]} name="Highest Score" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {activeTab === 'class' && (
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-[400px]">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-gray-800">Class Performance Comparison</h3>
                <select 
                  className="bg-gray-50 border border-gray-200 rounded-lg px-3 py-1 text-sm outline-none"
                  value={selectedClass}
                  onChange={(e) => setSelectedClass(e.target.value)}
                >
                  {data.classes.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <ResponsiveContainer width="100%" height="80%">
                <AreaChart data={classPerformanceData}>
                  <defs>
                    <linearGradient id="colorAvg" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Area type="monotone" dataKey="average" stroke="#8b5cf6" fillOpacity={1} fill="url(#colorAvg)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          )}

          {activeTab === 'student' && selectedStudent && (
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-[400px]">
              <h3 className="text-lg font-bold text-gray-800 mb-6">
                Subject Mastery Radar: <span className="text-blue-600">{selectedStudent.name}</span>
              </h3>
              <ResponsiveContainer width="100%" height="80%">
                <RadarChart cx="50%" cy="50%" outerRadius="80%" data={studentRadarData}>
                  <PolarGrid />
                  <PolarAngleAxis dataKey="subject" />
                  <PolarRadiusAxis angle={30} domain={[0, 100]} />
                  <Radar name={selectedStudent.name} dataKey="score" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.6} />
                  <Radar name="School Avg" dataKey="average" stroke="#94a3b8" fill="#94a3b8" fillOpacity={0.1} />
                  <Legend />
                  <Tooltip />
                </RadarChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>

        {/* Sidebar / List */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col h-fit">
          <div className="relative mb-6">
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input 
              type="text" 
              placeholder="Search students..." 
              className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <h4 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">Top Performers</h4>
          <div className="space-y-4">
            {filteredStudents.map((student, idx) => (
              <button 
                key={student.id}
                onClick={() => {
                  setSelectedStudentId(student.id);
                  setActiveTab('student');
                }}
                className={`w-full text-left p-3 rounded-xl transition-all border flex items-center justify-between group ${
                  selectedStudentId === student.id 
                  ? 'bg-blue-50 border-blue-200 shadow-sm' 
                  : 'hover:bg-gray-50 border-transparent'
                }`}
              >
                <div>
                  <p className="font-medium text-gray-800">{student.name}</p>
                  <p className="text-xs text-gray-500">{student.class} • Rank #{student.rankInSchool}</p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-blue-600">{student.totalScore}</p>
                  <ChevronRight className={`w-4 h-4 text-gray-300 transition-transform ${selectedStudentId === student.id ? 'translate-x-1 text-blue-400' : ''}`} />
                </div>
              </button>
            ))}
          </div>

          <div className="mt-8 pt-6 border-t border-gray-100">
             <h4 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">Quick Stats</h4>
             <div className="space-y-3">
               <div className="flex justify-between text-sm">
                 <span className="text-gray-500">Passing Rate (>60%)</span>
                 <span className="font-bold">{(data.students.filter(s => s.averageScore >= 60).length / data.students.length * 100).toFixed(0)}%</span>
               </div>
               <div className="flex justify-between text-sm">
                 <span className="text-gray-500">Excellence Rate (>90%)</span>
                 <span className="font-bold text-green-600">{(data.students.filter(s => s.averageScore >= 90).length / data.students.length * 100).toFixed(0)}%</span>
               </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ icon: React.ReactNode; title: string; value: string; subtitle: string }> = ({ icon, title, value, subtitle }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex items-start gap-4">
    <div className="p-3 rounded-xl bg-gray-50">{icon}</div>
    <div>
      <p className="text-sm text-gray-500 mb-1">{title}</p>
      <h3 className="text-2xl font-bold text-gray-900">{value}</h3>
      <p className="text-xs text-gray-400 mt-1">{subtitle}</p>
    </div>
  </div>
);

export default Dashboard;

