import React, { useCallback } from 'react';
import { Upload, FileSpreadsheet, AlertCircle } from 'lucide-react';
import { StudentRecord, AnalysisState } from '../types';

interface FileUploadProps {
  onDataLoaded: (data: AnalysisState) => void;
  setLoading: (loading: boolean) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded, setLoading }) => {
  const handleFileUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = window.XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = window.XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) throw new Error("Empty file");

        const firstRow = data[0];
        const keys = Object.keys(firstRow);

        // Identify special columns
        const nameCol = keys.find(k => k.includes('名') || k.toLowerCase().includes('name')) || keys[0];
        const classCol = keys.find(k => k.includes('班') || k.toLowerCase().includes('class')) || keys[1];
        const subjectCols = keys.filter(k => k !== nameCol && k !== classCol);

        const students: StudentRecord[] = data.map((row: any, index: number) => {
          const scores: Record<string, number> = {};
          let total = 0;
          subjectCols.forEach(sub => {
            const score = parseFloat(row[sub]) || 0;
            scores[sub] = score;
            total += score;
          });

          return {
            id: `s-${index}`,
            name: String(row[nameCol]),
            class: String(row[classCol]),
            scores,
            totalScore: total,
            averageScore: total / subjectCols.length
          };
        });

        // Calculate rankings
        students.sort((a, b) => b.totalScore - a.totalScore);
        students.forEach((s, idx) => s.rankInSchool = idx + 1);

        const classes = [...new Set(students.map(s => s.class))];
        classes.forEach(cls => {
          const classStudents = students.filter(s => s.class === cls);
          classStudents.sort((a, b) => b.totalScore - a.totalScore);
          classStudents.forEach((s, idx) => s.rankInClass = idx + 1);
        });

        // School stats
        const subjectStats: Record<string, any> = {};
        subjectCols.forEach(sub => {
          const vals = students.map(s => s.scores[sub]);
          subjectStats[sub] = {
            average: vals.reduce((a, b) => a + b, 0) / vals.length,
            max: Math.max(...vals),
            min: Math.min(...vals)
          };
        });

        onDataLoaded({
          students,
          subjects: subjectCols,
          classes,
          schoolStats: {
            // Fix: Operator '+' cannot be applied to types 'number' and 'StudentRecord'. 
            // Correctly access totalScore from student record during reduction.
            average: students.reduce((acc, s) => acc + s.totalScore, 0) / students.length,
            max: Math.max(...students.map(s => s.totalScore)),
            min: Math.min(...students.map(s => s.totalScore)),
            subjectStats
          }
        });
      } catch (err) {
        alert("Failed to parse Excel file. Please ensure it follows a standard format (Name, Class, Subjects...).");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  }, [onDataLoaded, setLoading]);

  return (
    <div className="flex flex-col items-center justify-center w-full p-12 border-2 border-dashed border-blue-200 rounded-2xl bg-white shadow-sm hover:border-blue-400 transition-all">
      <div className="bg-blue-50 p-4 rounded-full mb-4">
        <FileSpreadsheet className="w-12 h-12 text-blue-600" />
      </div>
      <h3 className="text-xl font-semibold text-gray-800 mb-2">Upload Grade Data</h3>
      <p className="text-gray-500 text-center max-w-sm mb-6">
        Upload your .xlsx file containing student names, classes, and subject scores.
      </p>
      <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg font-medium shadow-md transition-colors flex items-center gap-2">
        <Upload className="w-5 h-5" />
        Choose Excel File
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
      </label>
      <div className="mt-8 flex gap-4 text-xs text-gray-400 items-center">
        <div className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" />
          Supports multiple subjects
        </div>
        <div className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" />
          Auto rank calculation
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisState } from "../types";

export const getAIInsights = async (analysis: AnalysisState) => {
  // Always use a named parameter and direct process.env.API_KEY as per guidelines.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summary = {
    totalStudents: analysis.students.length,
    classes: analysis.classes,
    subjects: analysis.subjects,
    schoolAverage: analysis.schoolStats.average,
    subjectAverages: analysis.schoolStats.subjectStats
  };

  const prompt = `
    Based on the following student performance data summary, provide 4 critical insights for educators:
    Data Summary: ${JSON.stringify(summary)}

    The insights should cover:
    1. Overall academic health of the school.
    2. Specific subjects that need attention (weakest performance).
    3. High-performing areas to be maintained.
    4. Actionable pedagogical recommendations.

    Return the insights in a structured JSON format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: {
                type: Type.STRING,
                description: 'Brief title of the insight.'
              },
              content: {
                type: Type.STRING,
                description: 'Detailed explanation of the insight.'
              },
              type: {
                type: Type.STRING,
                description: 'Category of the insight: success, warning, or info.'
              }
            },
            required: ["title", "content", "type"]
          }
        }
      }
    });

    // Directly access the .text property (not a method) and trim whitespace.
    const jsonStr = response.text?.trim() || "[]";
    return JSON.parse(jsonStr);
  } catch (error) {
    console.error("AI Insights Error:", error);
    return [
      {
        title: "Analysis Available",
        content: "Data processed successfully. Explore the charts below for detailed breakdowns.",
        type: "info"
      }
    ];
  }
};

export interface ScoreSnapshot {
  period: string; // e.g., "Term 1", "2023-Q1", or "Exam 1"
  totalScore: number;
  averageScore: number;
  scores: Record<string, number>;
