declare global {
  interface Window {
    XLSX: any;
  }
}

import React, { useCallback } from 'react';
import { Upload, FileSpreadsheet, AlertCircle } from 'lucide-react';
import { StudentRecord, AnalysisState, ScoreSnapshot } from '../types';

interface FileUploadProps {
  onDataLoaded: (data: AnalysisState) => void;
  setLoading: (loading: boolean) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded, setLoading }) => {
  const handleFileUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = window.XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = window.XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) throw new Error("Empty file");

        const firstRow = data[0];
        const keys = Object.keys(firstRow);

        // Identify special columns
        const nameCol = keys.find(k => k.includes('名') || k.toLowerCase().includes('name')) || keys[0];
        const classCol = keys.find(k => k.includes('班') || k.toLowerCase().includes('class')) || keys[1];
        const periodCol = keys.find(k => k.includes('期') || k.includes('次') || k.toLowerCase().includes('period') || k.toLowerCase().includes('term') || k.toLowerCase().includes('date'));
        const subjectCols = keys.filter(k => k !== nameCol && k !== classCol && k !== periodCol);

        // Group rows by student to handle history
        const studentMap = new Map<string, any[]>();
        data.forEach((row: any) => {
          const name = String(row[nameCol]);
          if (!studentMap.has(name)) studentMap.set(name, []);
          studentMap.get(name)?.push(row);
        });

        const students: StudentRecord[] = Array.from(studentMap.entries()).map(([name, rows], index) => {
          // Sort rows by period if period column exists
          const sortedRows = periodCol ? rows.sort((a, b) => String(a[periodCol]).localeCompare(String(b[periodCol]))) : rows;

          const history: ScoreSnapshot[] = sortedRows.map(row => {
            const scores: Record<string, number> = {};
            let total = 0;
            subjectCols.forEach(sub => {
              const score = parseFloat(row[sub]) || 0;
              scores[sub] = score;
              total += score;
            });
            return {
              period: periodCol ? String(row[periodCol]) : "Current",
              scores,
              totalScore: total,
              averageScore: total / subjectCols.length
            };
          });

          const latest = history[history.length - 1];

          return {
            id: `s-${index}`,
            name,
            class: String(rows[0][classCol]),
            scores: latest.scores,
            totalScore: latest.totalScore,
            averageScore: latest.averageScore,
            history
          };
        });

        // Calculate rankings based on latest snapshot
        students.sort((a, b) => b.totalScore - a.totalScore);
        students.forEach((s, idx) => s.rankInSchool = idx + 1);

        const classes = [...new Set(students.map(s => s.class))];
        classes.forEach(cls => {
          const classStudents = students.filter(s => s.class === cls);
          classStudents.sort((a, b) => b.totalScore - a.totalScore);
          classStudents.forEach((s, idx) => s.rankInClass = idx + 1);
        });

        // Distribution stats
        const dist = [
          { name: 'Excellent (≥90)', value: 0, color: '#10b981' },
          { name: 'Good (80-89)', value: 0, color: '#3b82f6' },
          { name: 'Fair (70-79)', value: 0, color: '#f59e0b' },
          { name: 'Pass (60-69)', value: 0, color: '#6366f1' },
          { name: 'Fail (<60)', value: 0, color: '#ef4444' },
        ];

        students.forEach(s => {
          const avg = s.averageScore;
          if (avg >= 90) dist[0].value++;
          else if (avg >= 80) dist[1].value++;
          else if (avg >= 70) dist[2].value++;
          else if (avg >= 60) dist[3].value++;
          else dist[4].value++;
        });

        // School stats
        const subjectStats: Record<string, any> = {};
        subjectCols.forEach(sub => {
          const vals = students.map(s => s.scores[sub]);
          subjectStats[sub] = {
            average: vals.reduce((a, b) => a + b, 0) / vals.length,
            max: Math.max(...vals),
            min: Math.min(...vals)
          };
        });

        onDataLoaded({
          students,
          subjects: subjectCols,
          classes,
          schoolStats: {
            average: students.reduce((acc, s) => acc + s.totalScore, 0) / students.length,
            max: Math.max(...students.map(s => s.totalScore)),
            min: Math.min(...students.map(s => s.totalScore)),
            subjectStats,
            distribution: dist.filter(d => d.value > 0)
          }
        });
      } catch (err) {
        console.error(err);
        alert("Failed to parse file. Check format: Name, Class, [Subjects...], and optional Period/Term.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  }, [onDataLoaded, setLoading]);

  return (
    <div className="flex flex-col items-center justify-center w-full p-12 border-2 border-dashed border-blue-200 rounded-2xl bg-white shadow-sm hover:border-blue-400 transition-all">
      <div className="bg-blue-50 p-4 rounded-full mb-4">
        <FileSpreadsheet className="w-12 h-12 text-blue-600" />
      </div>
      <h3 className="text-xl font-semibold text-gray-800 mb-2">Upload Academic Records</h3>
      <p className="text-gray-500 text-center max-w-sm mb-6">
        Upload .xlsx files. Include columns for Name, Class, and Scores. 
        Add a "Term" or "Date" column for trend analysis.
      </p>
      <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg font-medium shadow-md transition-colors flex items-center gap-2">
        <Upload className="w-5 h-5" />
        Choose Excel File
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
      </label>
      <div className="mt-8 flex gap-6 text-xs text-gray-400 items-center">
        <div className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" />
          Multi-period Trend Support
        </div>
        <div className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" />
          Subject Correlation Analysis
        </div>
      </div>
    </div>
  );
};

