              const ws = wb.Sheets[wb.SheetNames[0]];
              const data = window.XLSX.utils.sheet_to_json(ws);

              if (data.length === 0) {
                resolve();
                return;
              }

              const keys = Object.keys(data[0] as object);
              const nameCol = keys.find(k => k.includes('名') || k.toLowerCase().includes('name')) || keys[0];
              const classCol = keys.find(k => k.includes('班') || k.toLowerCase().includes('class')) || keys[1];
              const subjectCols = keys.filter(k => k !== nameCol && k !== classCol);

              subjectCols.forEach(s => allSubjects.add(s));

              data.forEach((row: any) => {
                const name = String(row[nameCol]);
                const className = String(row[classCol]);

                const scores: Record<string, number> = {};
                let total = 0;
                subjectCols.forEach(sub => {
                  const score = parseFloat(row[sub]) || 0;
                  scores[sub] = score;
                  total += score;
                });

                const snapshot: ScoreSnapshot = {
                  period: periodName,
                  scores,
                  totalScore: total,
                  averageScore: total / subjectCols.length
                };

                if (!studentMap.has(name)) {
                  studentMap.set(name, { class: className, history: [] });
                }
                studentMap.get(name)?.history.push(snapshot);
              });
              resolve();
            } catch (err) {
              reject(err);
            }
          };
          reader.onerror = reject;
          reader.readAsBinaryString(file);
        });
      });

      await Promise.all(filePromises);

      const subjects = Array.from(allSubjects);
      const students: StudentRecord[] = Array.from(studentMap.entries()).map(([name, info], index) => {
        // Ensure history is sorted if it wasn't already (though we sorted files)
        const history = info.history;
        const latest = history[history.length - 1];

        return {
          id: `s-${index}`,
          name,
          class: info.class,
          scores: latest.scores,
          totalScore: latest.totalScore,
          averageScore: latest.averageScore,
          history: history
        };
      });

      if (students.length === 0) throw new Error("No student data found");

      // Sort and Rank based on LATEST exam
      students.sort((a, b) => b.totalScore - a.totalScore);
      students.forEach((s, idx) => s.rankInSchool = idx + 1);

      const classes = [...new Set(students.map(s => s.class))];
      classes.forEach(cls => {
        const classStudents = students.filter(s => s.class === cls);
        classStudents.sort((a, b) => b.totalScore - a.totalScore);
        classStudents.forEach((s, idx) => s.rankInClass = idx + 1);
      });

      // Stats
      const dist = [
        { name: 'Excellent (≥90)', value: 0, color: '#10b981' },
        { name: 'Good (80-89)', value: 0, color: '#3b82f6' },
        { name: 'Fair (70-79)', value: 0, color: '#f59e0b' },
        { name: 'Pass (60-69)', value: 0, color: '#6366f1' },
        { name: 'Fail (<60)', value: 0, color: '#ef4444' },
      ];

      students.forEach(s => {
        const avg = s.averageScore;
        if (avg >= 90) dist[0].value++;
        else if (avg >= 80) dist[1].value++;
        else if (avg >= 70) dist[2].value++;
        else if (avg >= 60) dist[3].value++;
        else dist[4].value++;
      });

      const subjectStats: Record<string, any> = {};
      subjects.forEach(sub => {
        const vals = students.map(s => s.scores[sub] || 0);
        subjectStats[sub] = {
          average: vals.reduce((a, b) => a + b, 0) / vals.length,
          max: Math.max(...vals),
          min: Math.min(...vals)
        };
      });

      onDataLoaded({
        students,
        subjects,
        classes,
        schoolStats: {
          average: students.reduce((acc, s) => acc + s.totalScore, 0) / students.length,
          max: Math.max(...students.map(s => s.totalScore)),
          min: Math.min(...students.map(s => s.totalScore)),
          subjectStats,
          distribution: dist.filter(d => d.value > 0)
        }
      });
    } catch (err) {
      console.error(err);
      alert("Error processing files. Please ensure they are valid Excel tables.");
    } finally {
      setLoading(false);
    }
  }, [onDataLoaded, setLoading]);

  const onDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") setDragActive(true);
    else if (e.type === "dragleave") setDragActive(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files) processFiles(e.dataTransfer.files);
  };

  return (
    <div 
      className={`relative flex flex-col items-center justify-center w-full p-12 border-2 border-dashed rounded-2xl bg-white shadow-sm transition-all duration-300 ${
        dragActive ? 'border-blue-600 bg-blue-50 scale-[1.01]' : 'border-blue-200 hover:border-blue-400'
      }`}
      onDragEnter={onDrag}
      onDragLeave={onDrag}
      onDragOver={onDrag}
      onDrop={onDrop}
    >
      <div className="bg-blue-50 p-4 rounded-full mb-4 group-hover:scale-110 transition-transform">
        <Files className="w-12 h-12 text-blue-600" />
      </div>
      <h3 className="text-xl font-bold text-gray-800 mb-2">Import Multiple Exams</h3>
      <p className="text-gray-500 text-center max-w-sm mb-6 text-sm">
        Select all your exam Excel files at once. We'll automatically merge records and build a chronological timeline for each student.
      </p>

      <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg font-medium shadow-md transition-all flex items-center gap-2 active:scale-95">
        <Upload className="w-5 h-5" />
        Select Files
        <input 
          type="file" 
          className="hidden" 
          accept=".xlsx, .xls" 
          multiple 
          onChange={(e) => processFiles(e.target.files)} 
        />
      </label>

      <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 text-xs text-gray-400 w-full max-w-md">
        <div className="flex items-center gap-2 bg-gray-50 p-2 rounded-lg border border-gray-100">
          <CheckCircle2 className="w-4 h-4 text-green-500" />
          <span>Auto-sort by filename</span>
        </div>
        <div className="flex items-center gap-2 bg-gray-50 p-2 rounded-lg border border-gray-100">
          <CheckCircle2 className="w-4 h-4 text-green-500" />
          <span>Intelligent Student Merging</span>
        </div>
        <div className="flex items-center gap-2 bg-gray-50 p-2 rounded-lg border border-gray-100">
          <CheckCircle2 className="w-4 h-4 text-green-500" />
          <span>Full Trend Analysis</span>
        </div>
        <div className="flex items-center gap-2 bg-gray-50 p-2 rounded-lg border border-gray-100">
          <CheckCircle2 className="w-4 h-4 text-green-500" />
          <span>Multi-subject Support</span>
        </div>
      </div>
    </div>
  );
};

