  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const fetchAI = async () => {
      setAiLoading(true);
      const insights = await getAIInsights(data);
      setAiInsights(insights);
      setAiLoading(false);
    };
    fetchAI();
  }, [data]);

  const selectedStudent = useMemo(() => 
    data.students.find(s => s.id === selectedStudentId), 
    [data.students, selectedStudentId]
  );

  // --- DATA COMPUTATIONS FOR NEW CHARTS ---

  // 1. Class Comparison: Subject Averages
  const classComparisonData = useMemo(() => {
    return data.subjects.map(sub => {
      const entry: any = { name: sub };
      selectedClasses.forEach(cls => {
        const clsStudents = data.students.filter(s => s.class === cls);
        const avg = clsStudents.reduce((acc, s) => acc + (s.scores[sub] || 0), 0) / clsStudents.length;
        entry[cls] = parseFloat(avg.toFixed(2));
      });
      return entry;
    });
  }, [data.students, data.subjects, selectedClasses]);

  // 2. Class Comparison: Ranking Buckets (Top 10, 20, 50, 100, 200, 400)
  const rankingBuckets = [10, 20, 50, 100, 200, 400];
  const rankingDistributionData = useMemo(() => {
    return rankingBuckets.map(bucket => {
      const entry: any = { name: `Top ${bucket}` };
      selectedClasses.forEach(cls => {
        const count = data.students.filter(s => s.class === cls && (s.rankInSchool || 999) <= bucket).length;
        entry[cls] = count;
      });
      return entry;
    });
  }, [data.students, selectedClasses]);

  // 3. Kings: Class Max vs Grade Max
  const kingsData = useMemo(() => {
    return data.subjects.map(sub => ({
      subject: sub,
      classMax: Math.max(...data.students.filter(s => s.class === benchmarkClass).map(s => s.scores[sub] || 0)),
      gradeMax: data.schoolStats.subjectStats[sub].max
    }));
  }, [data.students, data.subjects, benchmarkClass, data.schoolStats.subjectStats]);

  // 4. Kings: Class #1 vs School #1
  const duelData = useMemo(() => {
    const classFirst = data.students.filter(s => s.class === benchmarkClass).sort((a,b) => b.totalScore - a.totalScore)[0];
    const schoolFirst = data.students.sort((a,b) => b.totalScore - a.totalScore)[0];

    return data.subjects.map(sub => ({
      subject: sub,
      classFirst: classFirst?.scores[sub] || 0,
      schoolFirst: schoolFirst?.scores[sub] || 0
    }));
  }, [data.students, data.subjects, benchmarkClass]);

  const filteredStudents = data.students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase())
  ).slice(0, 10);

  const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
