                >
                  {data.classes.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>

              <ChartContainer title={`👑 Class ${benchmarkClass} King vs Grade King`}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={kingsData} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" horizontal={true} stroke="#f1f5f9" />
                    <XAxis type="number" domain={[0, 100]} stroke="#94a3b8" fontSize={12} />
                    <YAxis dataKey="subject" type="category" stroke="#94a3b8" fontSize={12} />
                    <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                    <Legend verticalAlign="top" align="center" iconType="diamond" />
                    <Bar dataKey="classMax" name="Class Top" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20} />
                    <Bar dataKey="gradeMax" name="Grade Top" fill="#e2e8f0" radius={[0, 4, 4, 0]} barSize={10} />
                  </BarChart>
                </ResponsiveContainer>
              </ChartContainer>

              <ChartContainer title="🔍 First-in-Class vs First-in-Grade Duel">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={duelData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="subject" stroke="#94a3b8" fontSize={12} />
                    <YAxis stroke="#94a3b8" fontSize={12} />
                    <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                    <Legend />
                    <Bar dataKey="classFirst" name={`#1 in ${benchmarkClass}`} fill="#8b5cf6" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="schoolFirst" name="#1 in School" fill="#ec4899" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </ChartContainer>
            </div>
          )}

          {/* TAB: STUDENT DETAIL */}
          {activeTab === 'student' && selectedStudent && (
            <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
              <ChartContainer title="📈 Performance Trend Curve">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={selectedStudent.history}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="period" stroke="#94a3b8" fontSize={12} />
                    <YAxis domain={['auto', 'auto']} stroke="#94a3b8" fontSize={12} />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                    <Legend verticalAlign="top" height={36}/>
                    <Line type="monotone" dataKey="averageScore" name="Avg Score" stroke="#3b82f6" strokeWidth={4} dot={{r: 6, fill: '#3b82f6', strokeWidth: 2, stroke: '#fff'}} />
                    <Line type="monotone" dataKey="totalScore" name="Total Score" stroke="#94a3b8" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                  </LineChart>
                </ResponsiveContainer>
              </ChartContainer>

              <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                <div className="px-6 py-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
                  <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <TableIcon className="w-3 h-3" /> Historical Grade Ledger
                  </h3>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead>
                      <tr className="bg-white text-gray-400 font-bold border-b border-gray-50">
                        <th className="px-6 py-4">Period</th>
                        {data.subjects.map(s => <th key={s} className="px-6 py-4">{s}</th>)}
                        <th className="px-6 py-4 text-blue-600">Avg</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                      {selectedStudent.history.map((h, i) => (
                        <tr key={i} className="hover:bg-blue-50/30 transition-colors">
                          <td className="px-6 py-4 font-bold text-gray-700">{h.period}</td>
                          {data.subjects.map(s => (
                            <td key={s} className="px-6 py-4 text-gray-600">{h.scores[s] || '-'}</td>
                          ))}
                          <td className="px-6 py-4 font-black text-blue-600">{h.averageScore.toFixed(1)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* SIDEBAR */}
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <div className="relative mb-6">
              <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
              <input 
                type="text" placeholder="Search student..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all"
              />
            </div>
            <div className="space-y-2 max-h-[500px] overflow-y-auto pr-1 custom-scrollbar">
              {filteredStudents.map((s) => (
                <button 
                  key={s.id} onClick={() => { setSelectedStudentId(s.id); setActiveTab('student'); }}
                  className={`w-full text-left p-4 rounded-xl border transition-all flex items-center justify-between group ${
                    selectedStudentId === s.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white hover:bg-gray-50 border-gray-100'
                  }`}
                >
                  <div className="flex flex-col">
                    <p className={`font-bold ${selectedStudentId === s.id ? 'text-white' : 'text-gray-900'}`}>{s.name}</p>
                    <p className={`text-[10px] ${selectedStudentId === s.id ? 'text-blue-100' : 'text-gray-400'}`}>{s.class} • Rank #{s.rankInSchool}</p>
                  </div>
                  <ChevronRight className={`w-4 h-4 transition-transform group-hover:translate-x-1 ${selectedStudentId === s.id ? 'text-white' : 'text-gray-300'}`} />
                </button>
              ))}
            </div>
          </div>

          {selectedStudent && (
             <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-6 rounded-2xl shadow-xl text-white">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-md">
                    <GraduationCap className="w-6 h-6" />
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] opacity-60 uppercase font-black">Latest Rank</p>
                    <p className="text-2xl font-black">#{selectedStudent.rankInSchool}</p>
                  </div>
                </div>
                <h4 className="text-lg font-bold mb-1">{selectedStudent.name}</h4>
                <p className="text-xs opacity-70 mb-4">{selectedStudent.class} Athlete of Academics</p>
                <div className="grid grid-cols-2 gap-4 pt-4 border-t border-white/10">
                   <div>
                     <p className="text-[9px] opacity-50 uppercase mb-0.5">Avg Score</p>
                     <p className="text-lg font-bold">{selectedStudent.averageScore.toFixed(1)}</p>
                   </div>
                   <div>
                     <p className="text-[9px] opacity-50 uppercase mb-0.5">Improvement</p>
                     <p className="text-lg font-bold">
                       {selectedStudent.history.length > 1 
                         ? ((selectedStudent.history[selectedStudent.history.length-1].averageScore - selectedStudent.history[0].averageScore) / selectedStudent.history[0].averageScore * 100).toFixed(1) + '%'
                         : '0.0%'
                       }
                     </p>
                   </div>
                </div>
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

