              <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded bg-sky-200" /> <span className="text-[10px] text-gray-500">高分线</span></div>
              <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded bg-teal-200" /> <span className="text-[10px] text-gray-500">名校线</span></div>
              <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded bg-emerald-200" /> <span className="text-[10px] text-gray-500">特控线</span></div>
            </div>
          </div>
        </>
      ) : (
        <div className="bg-white py-20 rounded-3xl border border-gray-100 shadow-sm text-center"><h3 className="text-xl font-bold text-gray-800">Please select a student above</h3></div>
      )}
    </div>
  );
};

