              <Legend verticalAlign="top" align="right" />
              {selectedClasses.map((cls, idx) => (
                <Bar key={cls} dataKey={cls} fill={colors[idx % colors.length]} radius={[4, 4, 0, 0]} />
              ))}
            </BarChart>
