import React, { useState, useEffect, useMemo } from 'react';
import { Users, Layers, Target, Award, History, Crown, Calculator, Calendar, BarChart3, Download } from 'lucide-react';
import { AnalysisState, AIInsight } from '../types';
import { getAIInsights } from '../services/geminiService';
import { StatCard, TabButton } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';

// View Imports
import SchoolView from './SchoolView';
import ClassComparisonView from './ClassComparisonView';
import EliteBenchmarksView from './EliteBenchmarksView';
import ExamParametersView from './ExamParametersView';
import StudentDetailView from './StudentDetailView';
import SubjectAnalysisView from './SubjectAnalysisView';
import ExportDataView from './ExportDataView';

// Fix: Define colors for charts and comparisons to resolve "Cannot find name 'colors'" errors
const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316'];

const Dashboard: React.FC<{ data: AnalysisState }> = ({ data }) => {
  const [activeTab, setActiveTab] = useState<'school' | 'comparison' | 'kings' | 'subjectAnalysis' | 'parameters' | 'student' | 'export'>('school');

  const allPeriods = useMemo(() => 
    data.students[0]?.history.map(h => h.period) || [], 
    [data.students]
  );

  const [selectedPeriod, setSelectedPeriod] = useState<string>(allPeriods[allPeriods.length - 1] || '');
  const [selectedClasses, setSelectedClasses] = useState<string[]>([data.classes[0]]);
  const [benchmarkClass, setBenchmarkClass] = useState(data.classes[0]);
  const [selectedStudentId, setSelectedStudentId] = useState(data.students[0]?.id);
  const [aiInsights, setAiInsights] = useState<AIInsight[]>([]);
  const [aiLoading, setAiLoading] = useState(true);

  const [studentSearchTerm, setStudentSearchTerm] = useState('');
  const [classFilter, setClassFilter] = useState<string>('all');

  const [thresholdType, setThresholdType] = useState<'rank' | 'percent'>('rank');
  const [thresholds, setThresholds] = useState<Record<string, number>>({
    '清北': 5, 'C9': 30, '高分数': 100, '名校': 300, '特控': 600,
  });

  // 1. 调用 Engine 计算全周期总分排名映射
  const allHistoricalRanks = useMemo(() => 
    AnalysisEngine.calculateHistoricalRanks(data.students), 
    [data.students]
  );

  // 1.1 调用 Engine 计算全周期单科排名映射
  const allSubjectRanks = useMemo(() => 
    AnalysisEngine.calculateSubjectHistoricalRanks(data.students, data.subjects),
    [data.students, data.subjects]
  );

  // 2. 调用 Engine 计算全周期年级平均分
  const gradeAveragesByPeriod = useMemo(() => 
    AnalysisEngine.calculateGradeAverages(data.students), 
    [data.students]
  );

  useEffect(() => {
    const fetchAI = async () => {
      setAiLoading(true);
      const insights = await getAIInsights(data);
      setAiInsights(insights);
      setAiLoading(false);
    };
    fetchAI();
  }, [data]);

  // 3. 构造当前所选周期的快照数据
  const periodData = useMemo(() => {
    if (!selectedPeriod) return [];
    const ranks = allHistoricalRanks[selectedPeriod] || {};
    return data.students.map(s => {
      const historyItem = s.history.find(h => h.period === selectedPeriod);
      return {
        ...s,
        currentTotal: historyItem?.totalScore || 0,
        currentAverage: historyItem?.averageScore || 0,
        currentScores: historyItem?.scores || {},
        periodSchoolRank: ranks[s.name] || 9999
      };
    }).sort((a, b) => a.periodSchoolRank - b.periodSchoolRank);
  }, [data.students, selectedPeriod, allHistoricalRanks]);

  // 4. 调用 Engine 计算考试统计参数
  const examParameters = useMemo(() => 
    AnalysisEngine.calculateExamParameters(periodData, data.subjects),
    [periodData, data.subjects]
  );

  // 以下为各视图所需的 derived data
  const aboveLineCount = useMemo(() => {
    const limit = thresholdType === 'rank' ? (thresholds['特控'] || 0) : Math.round(((thresholds['特控'] || 0) / 100) * periodData.length);
    return periodData.filter(s => s.periodSchoolRank <= limit).length;
  }, [periodData, thresholds, thresholdType]);

  const classComparisonData = useMemo(() => data.subjects.map(sub => {
    const entry: any = { name: sub };
    selectedClasses.forEach(cls => {
      const clsStudents = periodData.filter(s => s.class === cls);
      entry[cls] = clsStudents.length > 0 ? parseFloat((clsStudents.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / clsStudents.length).toFixed(2)) : 0;
    });
    return entry;
  }), [periodData, data.subjects, selectedClasses]);

  const rankingDistributionData = useMemo(() => [10, 20, 50, 100, 200, 400].map(bucket => {
    const entry: any = { name: `Top ${bucket}` };
    selectedClasses.forEach(cls => { entry[cls] = periodData.filter(s => s.class === cls && s.periodSchoolRank <= bucket).length; });
    return entry;
  }), [periodData, selectedClasses]);

  const kingsData = useMemo(() => data.subjects.map(sub => ({
    subject: sub,
    classMax: Math.max(...periodData.filter(s => s.class === benchmarkClass).map(s => s.currentScores[sub] || 0), 0),
    gradeMax: Math.max(...periodData.map(s => s.currentScores[sub] || 0), 0)
  })), [periodData, data.subjects, benchmarkClass]);

  const duelData = useMemo(() => {
    const classFirst = periodData.filter(s => s.class === benchmarkClass).sort((a,b) => b.currentTotal - a.currentTotal)[0];
    const schoolFirst = periodData[0];
    return data.subjects.map(sub => ({ subject: sub, classFirst: classFirst?.currentScores[sub] || 0, schoolFirst: schoolFirst?.currentScores[sub] || 0 }));
  }, [periodData, data.subjects, benchmarkClass]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard icon={<Users className="w-5 h-5 text-blue-600" />} title="Total Students" value={data.students.length.toString()} subtitle="Cohort Size" />
        <StatCard icon={<Layers className="w-5 h-5 text-green-600" />} title="Classes" value={data.classes.length.toString()} subtitle="Active Groups" />
        <StatCard icon={<Target className="w-5 h-5 text-purple-600" />} title="特控上线人数" value={aboveLineCount.toString()} subtitle={`Based on ${selectedPeriod}`} />
        <StatCard icon={<Award className="w-5 h-5 text-orange-600" />} title="Best Score" value={data.schoolStats.max.toString()} subtitle="School Record" />
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-start lg:items-center justify-between">
        <div className="flex flex-wrap gap-1 bg-white p-1.5 rounded-2xl shadow-sm border border-gray-100 w-fit">
          <TabButton active={activeTab === 'school'} onClick={() => setActiveTab('school')} icon={<History className="w-4 h-4"/>} label="School View" />
          <TabButton active={activeTab === 'comparison'} onClick={() => setActiveTab('comparison')} icon={<Layers className="w-4 h-4"/>} label="Class Comparison" />
          <TabButton active={activeTab === 'kings'} onClick={() => setActiveTab('kings')} icon={<Crown className="w-4 h-4"/>} label="Elite Benchmarks" />
          <TabButton active={activeTab === 'parameters'} onClick={() => setActiveTab('parameters')} icon={<Calculator className="w-4 h-4"/>} label="Exam Parameters" />
          <TabButton active={activeTab === 'subjectAnalysis'} onClick={() => setActiveTab('subjectAnalysis')} icon={<BarChart3 className="w-4 h-4"/>} label="Subject Analysis" />
          <TabButton active={activeTab === 'student'} onClick={() => setActiveTab('student')} icon={<Target className="w-4 h-4"/>} label="Student Detail" />
          <TabButton active={activeTab === 'export'} onClick={() => setActiveTab('export')} icon={<Download className="w-4 h-4"/>} label="Data Export" />
        </div>
        {activeTab !== 'student' && activeTab !== 'export' && (
          <div className="flex items-center gap-3 bg-blue-50/50 px-4 py-2 rounded-2xl border border-blue-100 animate-in slide-in-from-right-4">
            <Calendar className="w-4 h-4 text-blue-600" />
            <select className="bg-transparent border-none text-sm font-black text-blue-900 focus:ring-0 cursor-pointer" value={selectedPeriod} onChange={(e) => setSelectedPeriod(e.target.value)}>
              {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
        )}
      </div>

      <div className="w-full">
        {activeTab === 'school' && <SchoolView selectedPeriod={selectedPeriod} aiInsights={aiInsights} periodData={periodData} subjects={data.subjects} thresholds={thresholds} setThresholds={setThresholds} thresholdType={thresholdType} setThresholdType={setThresholdType} />}
        {activeTab === 'comparison' && <ClassComparisonView selectedPeriod={selectedPeriod} classes={data.classes} selectedClasses={selectedClasses} setSelectedClasses={setSelectedClasses} classComparisonData={classComparisonData} rankingDistributionData={rankingDistributionData} colors={colors} periodData={periodData} />}
        {activeTab === 'kings' && <EliteBenchmarksView selectedPeriod={selectedPeriod} classes={data.classes} benchmarkClass={benchmarkClass} setBenchmarkClass={setBenchmarkClass} kingsData={kingsData} duelData={duelData} />}
        {activeTab === 'parameters' && <ExamParametersView selectedPeriod={selectedPeriod} examParameters={examParameters} colors={colors} totalParticipants={periodData.length} />}
        {activeTab === 'subjectAnalysis' && (
          <SubjectAnalysisView 
            selectedPeriod={selectedPeriod}
            periodData={periodData}
            subjects={data.subjects}
            classes={data.classes}
            allSubjectRanks={allSubjectRanks}
            thresholds={thresholds}
            thresholdType={thresholdType}
            totalStudents={data.students.length}
          />
        )}
        {activeTab === 'student' && (
          <StudentDetailView 
            studentSearchTerm={studentSearchTerm} setStudentSearchTerm={setStudentSearchTerm} 
            classFilter={classFilter} setClassFilter={setClassFilter} classes={data.classes} 
            selectableStudents={data.students.filter(s => s.name.toLowerCase().includes(studentSearchTerm.toLowerCase()) && (classFilter === 'all' || s.class === classFilter))} 
            selectedStudentId={selectedStudentId} setSelectedStudentId={setSelectedStudentId} 
            selectedStudent={data.students.find(s => s.id === selectedStudentId)} 
            subjects={data.subjects} gradeAveragesByPeriod={gradeAveragesByPeriod} 
            allHistoricalRanks={allHistoricalRanks}
            allSubjectRanks={allSubjectRanks}
            thresholds={thresholds}
            thresholdType={thresholdType}
            totalStudents={data.students.length}
          />
        )}
        {activeTab === 'export' && (
          <ExportDataView 
            data={data}
            periodData={periodData}
            selectedPeriod={selectedPeriod}
            examParameters={examParameters}
            allHistoricalRanks={allHistoricalRanks}
          />
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Download, FileText, CheckCircle2, Table, Eye, Filter } from 'lucide-react';
import { AnalysisState, StudentRecord } from '../types';

interface ExportDataViewProps {
  data: AnalysisState;
  periodData: any[];
  selectedPeriod: string;
  examParameters: any;
  allHistoricalRanks: Record<string, Record<string, number>>;
}

const ExportDataView: React.FC<ExportDataViewProps> = ({
  data,
  periodData,
  selectedPeriod,
  examParameters,
  allHistoricalRanks
}) => {
  const [exportType, setExportType] = useState<'current_scores' | 'full_history' | 'exam_stats' | 'class_matrix'>('current_scores');
  const [selectedClasses, setSelectedClasses] = useState<string[]>(data.classes);

  const toggleClass = (cls: string) => {
    setSelectedClasses(prev => 
      prev.includes(cls) ? prev.filter(p => p !== cls) : [...prev, cls]
    );
  };

  const preparedData = useMemo(() => {
    if (exportType === 'current_scores') {
      return periodData
        .filter(s => selectedClasses.includes(s.class))
        .map(s => {
          const base: any = {
            'Name': s.name,
            'Class': s.class,
            'School Rank': s.periodSchoolRank,
            'Total Score': s.currentTotal,
            'Average': s.currentAverage.toFixed(2),
          };
          data.subjects.forEach(sub => {
            base[sub] = s.currentScores[sub] || 0;
          });
          return base;
        });
    } else if (exportType === 'full_history') {
      const rows: any[] = [];
      data.students
        .filter(s => selectedClasses.includes(s.class))
        .forEach(s => {
          s.history.forEach(h => {
            const row: any = {
              'Name': s.name,
              'Class': s.class,
              'Period': h.period,
              'School Rank': allHistoricalRanks[h.period]?.[s.name] || '-',
              'Total Score': h.totalScore,
              'Average': h.averageScore.toFixed(2),
            };
            data.subjects.forEach(sub => {
              row[sub] = h.scores[sub] || 0;
            });
            rows.push(row);
          });
        });
      return rows;
    } else if (exportType === 'exam_stats') {
      if (!examParameters) return [];
      return examParameters.subjectStats.map((s: any) => ({
        'Subject': s.subject,
        'Max Score': s.max,
        'Mean Score': s.mean,
        'Median': s.median,
        'Mode': s.mode,
        'Std Dev': s.stdDev,
        'Difficulty (L)': s.difficulty,
        'Discrimination (D)': s.discrimination
      }));
    } else if (exportType === 'class_matrix') {
      return data.classes.map(cls => {
        const clsStudents = periodData.filter(s => s.class === cls);
        const avg = clsStudents.length > 0 
          ? clsStudents.reduce((acc, s) => acc + s.currentTotal, 0) / clsStudents.length 
          : 0;

        const row: any = {
          'Class Name': cls,
          'Student Count': clsStudents.length,
          'Total Average': avg.toFixed(2),
        };

        data.subjects.forEach(sub => {
          const subAvg = clsStudents.length > 0
            ? clsStudents.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / clsStudents.length
            : 0;
          row[`${sub} Avg`] = subAvg.toFixed(2);
        });

        return row;
      });
    }
    return [];
  }, [exportType, periodData, data, selectedClasses, allHistoricalRanks, examParameters]);

  const handleExport = () => {
    if (preparedData.length === 0) return;

    const ws = window.XLSX.utils.json_to_sheet(preparedData);
    const wb = window.XLSX.utils.book_new();
    window.XLSX.utils.book_append_sheet(wb, ws, "Exported Data");

    const fileName = `EduAnalytics_${exportType}_${selectedPeriod.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}`;
    window.XLSX.writeFile(wb, `${fileName}.xlsx`);
  };

  const previewHeaders = preparedData.length > 0 ? Object.keys(preparedData[0]) : [];

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Selection Panel */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-6">
            <div>
              <h3 className="text-sm font-black text-gray-800 flex items-center gap-2 mb-4">
                <FileText className="w-4 h-4 text-blue-600" /> 1. Select Report Type
              </h3>
              <div className="space-y-3">
                {[
                  { id: 'current_scores', label: 'Latest Scores (Rankings)', desc: `Current view of ${selectedPeriod}` },
                  { id: 'full_history', label: 'Complete Chronological Data', desc: 'Timeline scores for all exams' },
                  { id: 'exam_stats', label: 'Subject Parameter Analysis', desc: 'Difficulty, discrimination, mean' },
                  { id: 'class_matrix', label: 'Class-by-Class Matrix', desc: 'Summary comparison metrics' },
                ].map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setExportType(item.id as any)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all ${
                      exportType === item.id 
                        ? 'bg-blue-600 border-blue-600 text-white shadow-lg' 
                        : 'bg-gray-50 border-gray-100 text-gray-700 hover:border-blue-300'
                    }`}
                  >
                    <p className="text-sm font-bold">{item.label}</p>
                    <p className={`text-[10px] mt-1 ${exportType === item.id ? 'text-blue-100' : 'text-gray-400'}`}>{item.desc}</p>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <h3 className="text-sm font-black text-gray-800 flex items-center gap-2 mb-4">
                <Filter className="w-4 h-4 text-indigo-600" /> 2. Filter Classes
              </h3>
              <div className="flex flex-wrap gap-2">
                {data.classes.map(cls => (
                  <button
                    key={cls}
                    onClick={() => toggleClass(cls)}
                    className={`px-3 py-1.5 rounded-xl text-[10px] font-black transition-all border ${
                      selectedClasses.includes(cls) 
                        ? 'bg-indigo-600 text-white border-indigo-600' 
                        : 'bg-gray-50 text-gray-400 border-gray-100'
                    }`}
                  >
                    {cls}
                  </button>
                ))}
              </div>
            </div>

            <button
              onClick={handleExport}
              disabled={preparedData.length === 0}
              className="w-full bg-gray-900 text-white py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2 hover:bg-gray-800 transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed shadow-xl"
            >
              <Download className="w-5 h-5" />
              Generate Excel Report
            </button>
          </div>
        </div>

        {/* Preview Panel */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden flex flex-col h-full">
            <div className="px-8 py-6 bg-gray-50/50 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                  <Eye className="w-4 h-4" /> Data Export Preview
                </h3>
                <p className="text-[10px] text-gray-400 mt-1">Showing first 10 rows of {preparedData.length} records</p>
              </div>
              <div className="bg-green-100 text-green-700 px-3 py-1 rounded-lg text-[10px] font-black flex items-center gap-1.5">
                <CheckCircle2 className="w-3 h-3" /> System Ready
              </div>
            </div>

            <div className="overflow-auto max-h-[600px] flex-1">
              {preparedData.length > 0 ? (
                <table className="w-full text-left text-xs border-collapse">
                  <thead className="sticky top-0 bg-white shadow-sm">
                    <tr>
                      {previewHeaders.map(h => (
                        <th key={h} className="px-6 py-4 font-black text-gray-400 border-b border-gray-50 bg-white">
                          {h}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {preparedData.slice(0, 10).map((row, idx) => (
                      <tr key={idx} className="hover:bg-blue-50/20 transition-colors">
                        {previewHeaders.map(h => (
                          <td key={h} className="px-6 py-4 text-gray-600 font-medium truncate max-w-[150px]">
                            {row[h]}
                          </td>
                        ))}
                      </tr>
                    ))}
                    {preparedData.length > 10 && (
                      <tr>
                        <td colSpan={previewHeaders.length} className="px-6 py-4 text-center text-gray-400 italic bg-gray-50/30">
                          ... and {preparedData.length - 10} more rows ...
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              ) : (
                <div className="flex flex-col items-center justify-center py-40 text-gray-300">
                  <Table className="w-12 h-12 mb-4 opacity-20" />
                  <p className="text-sm font-medium">No records match the current filters.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
        <h4 className="text-xs font-bold text-amber-900 uppercase tracking-widest mb-3">Export Notes</h4>
        <ul className="text-xs text-amber-800 space-y-2 list-disc list-inside opacity-80">
          <li>Standard .xlsx format compatible with Excel, Numbers, and Google Sheets.</li>
          <li>All student rankings are recalculated based on the chosen period and cohort.</li>
          <li>Ensure popup blockers are disabled for direct file downloads.</li>
        </ul>
      </div>
    </div>
  );
};

